1: #include <cuda_runtime.h>
2: #include <stddef.h>
3: 
4: /* Each warp computes four rows across 32 contiguous output columns. */
5: __global__ void sgemm_warp_register(int M, int N, int K, float alpha,
6:                                     const float *A, const float *B,
7:                                     float beta, float *C) {
8:   const int lane = threadIdx.x;
9:   const size_t row_base = static_cast<size_t>(blockIdx.y) * 16u +
10:                           static_cast<size_t>(threadIdx.y) * 4u;
11:   const size_t col = static_cast<size_t>(blockIdx.x) * 32u +
12:                      static_cast<size_t>(lane);
13:   const size_t m_size = static_cast<size_t>(M);
14:   const size_t n_size = static_cast<size_t>(N);
15:   constexpr unsigned int full_warp_mask = 0xffffffffu;
16: 
17:   float acc0 = 0.0f;
18:   float acc1 = 0.0f;
19:   float acc2 = 0.0f;
20:   float acc3 = 0.0f;
21: 
22:   for (int kk = 0; kk < K; ++kk) {
23:     const size_t b_index = static_cast<size_t>(kk) * n_size + col;
24:     const float b = col < n_size ? B[b_index] : 0.0f;
25: 
26:     float a0 = lane == 0 && row_base < m_size
27:                    ? A[row_base * static_cast<size_t>(K) +
28:                        static_cast<size_t>(kk)]
29:                    : 0.0f;
30:     float a1 = lane == 0 && row_base + 1u < m_size
31:                    ? A[(row_base + 1u) * static_cast<size_t>(K) +
32:                        static_cast<size_t>(kk)]
33:                    : 0.0f;
34:     float a2 = lane == 0 && row_base + 2u < m_size
35:                    ? A[(row_base + 2u) * static_cast<size_t>(K) +
36:                        static_cast<size_t>(kk)]
37:                    : 0.0f;
38:     float a3 = lane == 0 && row_base + 3u < m_size
39:                    ? A[(row_base + 3u) * static_cast<size_t>(K) +
40:                        static_cast<size_t>(kk)]
41:                    : 0.0f;
42: 
43:     a0 = __shfl_sync(full_warp_mask, a0, 0);
44:     a1 = __shfl_sync(full_warp_mask, a1, 0);
45:     a2 = __shfl_sync(full_warp_mask, a2, 0);
46:     a3 = __shfl_sync(full_warp_mask, a3, 0);
47: 
48:     acc0 = __fmaf_rn(a0, b, acc0);
49:     acc1 = __fmaf_rn(a1, b, acc1);
50:     acc2 = __fmaf_rn(a2, b, acc2);
51:     acc3 = __fmaf_rn(a3, b, acc3);
52:   }
53: 
54:   if (col < n_size) {
55:     if (row_base < m_size) {
56:       const size_t index = row_base * n_size + col;
57:       C[index] = alpha * acc0 + beta * C[index];
58:     }
59:     if (row_base + 1u < m_size) {
60:       const size_t index = (row_base + 1u) * n_size + col;
61:       C[index] = alpha * acc1 + beta * C[index];
62:     }
63:     if (row_base + 2u < m_size) {
64:       const size_t index = (row_base + 2u) * n_size + col;
65:       C[index] = alpha * acc2 + beta * C[index];
66:     }
67:     if (row_base + 3u < m_size) {
68:       const size_t index = (row_base + 3u) * n_size + col;
69:       C[index] = alpha * acc3 + beta * C[index];
70:     }
71:   }
72: }
73: 
74: extern "C" void run(const float *A, const float *B, float *C, float *scratch,
75:                     int n, int m, int k, float alpha, float beta) {
76:   (void)scratch;
77:   if (n <= 0 || m <= 0) {
78:     return;
79:   }
80: 
81:   const unsigned int grid_x = static_cast<unsigned int>(m / 32 + (m % 32 != 0));
82:   const unsigned int grid_y = static_cast<unsigned int>(n / 16 + (n % 16 != 0));
83:   sgemm_warp_register<<<dim3(grid_x, grid_y), dim3(32, 4)>>>(
84:       n, m, k, alpha, A, B, beta, C);
85: }

