1: #include <cuda_runtime.h>
2: 
3: namespace {
4: 
5: constexpr int kBlockX = 32;
6: constexpr int kBlockY = 8;
7: constexpr int kTileM = 16;
8: constexpr int kTileN = 64;
9: constexpr int kTileK = 32;
10: constexpr int kThreads = kBlockX * kBlockY;
11: 
12: template <bool Async>
13: __device__ __forceinline__ void copy_to_shared(float *dst, const float *src,
14:                                                bool valid) {
15:   if (!valid) {
16:     *dst = 0.0f;
17:     return;
18:   }
19: 
20:   if (Async) {
21:     const unsigned int shared_address =
22:         static_cast<unsigned int>(__cvta_generic_to_shared(dst));
23:     asm volatile("cp.async.ca.shared.global [%0], [%1], 4;"
24:                  :
25:                  : "r"(shared_address), "l"(src)
26:                  : "memory");
27:   } else {
28:     *dst = *src;
29:   }
30: }
31: 
32: template <bool Async>
33: __device__ __forceinline__ void commit_copies() {
34:   if (Async) {
35:     asm volatile("cp.async.commit_group;" ::: "memory");
36:   }
37: }
38: 
39: template <bool Async>
40: __device__ __forceinline__ void wait_for_copies() {
41:   if (Async) {
42:     asm volatile("cp.async.wait_group 0;" ::: "memory");
43:   }
44: }
45: 
46: template <bool Async>
47: __device__ __forceinline__ void stage_tile(
48:     const float *A, const float *B, int M, int N, int K, int row_origin,
49:     int col_origin, int k_origin, float *shared_a, float *shared_b) {
50:   const int tid = static_cast<int>(threadIdx.y) * kBlockX +
51:                   static_cast<int>(threadIdx.x);
52: 
53:   for (int i = tid; i < kTileM * kTileK; i += kThreads) {
54:     const int tile_row = i / kTileK;
55:     const int tile_k = i % kTileK;
56:     const int row = row_origin + tile_row;
57:     const int k = k_origin + tile_k;
58:     const bool valid = row < M && k < K;
59:     const float *src = valid
60:                            ? A + static_cast<unsigned long long>(row) * K + k
61:                            : A;
62:     copy_to_shared<Async>(&shared_a[i], src, valid);
63:   }
64: 
65:   for (int i = tid; i < kTileK * kTileN; i += kThreads) {
66:     const int tile_k = i / kTileN;
67:     const int tile_col = i % kTileN;
68:     const int k = k_origin + tile_k;
69:     const int col = col_origin + tile_col;
70:     const bool valid = k < K && col < N;
71:     const float *src = valid
72:                            ? B + static_cast<unsigned long long>(k) * N + col
73:                            : B;
74:     copy_to_shared<Async>(&shared_b[i], src, valid);
75:   }
76: }
