78: template <bool Async>
79: __global__ void sgemm_tiled(int M, int N, int K, float alpha, const float *A,
80:                             const float *B, float beta, float *C) {
81:   __shared__ float shared_a[2][kTileM * kTileK];
82:   __shared__ float shared_b[2][kTileK * kTileN];
83: 
84:   const int row_origin = static_cast<int>(blockIdx.y) * kTileM;
85:   const int col_origin = static_cast<int>(blockIdx.x) * kTileN;
86:   const int row0 = row_origin + static_cast<int>(threadIdx.y);
87:   const int row1 = row0 + kBlockY;
88:   const int col0 = col_origin + static_cast<int>(threadIdx.x);
89:   const int col1 = col0 + kBlockX;
90:   const int k_tiles = K / kTileK + ((K % kTileK) != 0);
91: 
92:   float acc00 = 0.0f;
93:   float acc01 = 0.0f;
94:   float acc10 = 0.0f;
95:   float acc11 = 0.0f;
96: 
97:   if (k_tiles > 0) {
98:     stage_tile<Async>(A, B, M, N, K, row_origin, col_origin, 0,
99:                       shared_a[0], shared_b[0]);
100:     commit_copies<Async>();
101:     wait_for_copies<Async>();
102:     __syncthreads();
103: 
104:     int current_buffer = 0;
105:     for (int tile = 0; tile < k_tiles; ++tile) {
106:       const bool has_next = tile + 1 < k_tiles;
107:       const int next_buffer = current_buffer ^ 1;
108:       if (has_next) {
109:         stage_tile<Async>(A, B, M, N, K, row_origin, col_origin,
110:                           (tile + 1) * kTileK, shared_a[next_buffer],
111:                           shared_b[next_buffer]);
112:         commit_copies<Async>();
113:       }
114: 
115:       for (int kk = 0; kk < kTileK; ++kk) {
116:         const float a0 = shared_a[current_buffer]
117:                                   [static_cast<int>(threadIdx.y) * kTileK + kk];
118:         const float a1 = shared_a[current_buffer]
119:                                   [(static_cast<int>(threadIdx.y) + kBlockY) *
120:                                        kTileK +
121:                                    kk];
122:         const float b0 = shared_b[current_buffer][kk * kTileN +
123:                                                    static_cast<int>(threadIdx.x)];
124:         const float b1 = shared_b[current_buffer]
125:                                   [kk * kTileN + static_cast<int>(threadIdx.x) +
126:                                    kBlockX];
127:         acc00 += a0 * b0;
128:         acc01 += a0 * b1;
129:         acc10 += a1 * b0;
130:         acc11 += a1 * b1;
131:       }
132: 
133:       if (has_next) {
134:         wait_for_copies<Async>();
135:         __syncthreads();
136:         current_buffer = next_buffer;
137:       }
138:     }
139:   }
140: 
141:   if (row0 < M && col0 < N) {
142:     const unsigned long long offset =
143:         static_cast<unsigned long long>(row0) * N + col0;
144:     C[offset] = alpha * acc00 + beta * C[offset];
145:   }
146:   if (row0 < M && col1 < N) {
147:     const unsigned long long offset =
148:         static_cast<unsigned long long>(row0) * N + col1;
149:     C[offset] = alpha * acc01 + beta * C[offset];
150:   }
151:   if (row1 < M && col0 < N) {
152:     const unsigned long long offset =
153:         static_cast<unsigned long long>(row1) * N + col0;
154:     C[offset] = alpha * acc10 + beta * C[offset];
155:   }
156:   if (row1 < M && col1 < N) {
157:     const unsigned long long offset =
158:         static_cast<unsigned long long>(row1) * N + col1;
159:     C[offset] = alpha * acc11 + beta * C[offset];
160:   }
161: }
162: 
163: template <bool Async>
164: void launch_sgemm(int M, int N, int K, float alpha, const float *A,
165:                   const float *B, float beta, float *C) {
166:   if (M <= 0 || N <= 0) {
167:     return;
168:   }
169: 
170:   const dim3 block(kBlockX, kBlockY);
171:   const dim3 grid(static_cast<unsigned int>((N - 1) / kTileN + 1),
172:                   static_cast<unsigned int>((M - 1) / kTileM + 1));
173:   sgemm_tiled<Async><<<grid, block>>>(M, N, K, alpha, A, B, beta, C);
174: }
175: 
176: }  // namespace
177: 
178: extern "C" void run(const float *A, const float *B, float *C, float *scratch,
179:                      int n, int m, int k, float alpha, float beta) {
180:   (void)scratch;
181:   launch_sgemm<true>(n, m, k, alpha, A, B, beta, C);
182: }
183: 
184: // Matched synchronous staging control; each entry point launches one kernel.
185: extern "C" void run_sync(const float *A, const float *B, float *C,
186:                           float *scratch, int n, int m, int k, float alpha,
187:                           float beta) {
188:   (void)scratch;
189:   launch_sgemm<false>(n, m, k, alpha, A, B, beta, C);
190: }

