1: #include <cuda_runtime.h>
2: 
3: #include <cstddef>
4: 
5: __global__ void sgemm_tiled(int M, int N, int K, float alpha, const float *A,
6:                             const float *B, float beta, float *C) {
7:   constexpr int BM = 64;
8:   constexpr int BN = 64;
9:   constexpr int BK = 64;
10: 
11:   __shared__ float tileA[BM][BK];
12:   __shared__ float tileB[BK][BN];
13: 
14:   const int tid = static_cast<int>(threadIdx.x);
15:   const int laneCol = tid & 31;
16:   const int rowGroup = tid >> 5;
17:   const int baseM = static_cast<int>(blockIdx.y) * BM;
18:   const int baseN = static_cast<int>(blockIdx.x) * BN;
19:   float accum[8][2] = {};
20: 
21:   for (int kBase = 0; kBase < K;) {
22:     const int validK = (K - kBase < BK) ? (K - kBase) : BK;
23: 
24:     for (int idx = tid; idx < BM * BK; idx += blockDim.x) {
25:       const int rowInTile = idx / BK;
26:       const int kInTile = idx % BK;
27:       const long long row = static_cast<long long>(baseM) + rowInTile;
28:       if (row < M && kInTile < validK) {
29:         const int globalK = kBase + kInTile;
30:         tileA[rowInTile][kInTile] =
31:             A[static_cast<std::size_t>(row) * K + globalK];
32:       } else {
33:         tileA[rowInTile][kInTile] = 0.0f;
34:       }
35:     }
36: 
37:     for (int idx = tid; idx < BK * BN; idx += blockDim.x) {
38:       const int kInTile = idx / BN;
39:       const int colInTile = idx % BN;
40:       const long long col = static_cast<long long>(baseN) + colInTile;
41:       if (col < N && kInTile < validK) {
42:         const int globalK = kBase + kInTile;
43:         tileB[kInTile][colInTile] =
44:             B[static_cast<std::size_t>(globalK) * N + col];
45:       } else {
46:         tileB[kInTile][colInTile] = 0.0f;
47:       }
48:     }
49: 
50:     __syncthreads();
51: 
52: #pragma unroll 4
53:     for (int kInTile = 0; kInTile < BK; ++kInTile) {
54:       const float b0 = tileB[kInTile][laneCol];
55:       const float b1 = tileB[kInTile][laneCol + 32];
56: #pragma unroll
57:       for (int r = 0; r < 8; ++r) {
58:         const float a = tileA[rowGroup * 8 + r][kInTile];
59:         accum[r][0] = fmaf(a, b0, accum[r][0]);
60:         accum[r][1] = fmaf(a, b1, accum[r][1]);
61:       }
62:     }
63: 
64:     __syncthreads();
65:     kBase += validK;
66:   }
67: 
68:   const int col0 = baseN + laneCol;
69:   const int col1 = col0 + 32;
70: #pragma unroll
71:   for (int r = 0; r < 8; ++r) {
72:     const long long row = static_cast<long long>(baseM) + rowGroup * 8 + r;
73:     if (row < M) {
74:       if (col0 < N) {
75:         const std::size_t index = static_cast<std::size_t>(row) * N + col0;
76:         const float product = alpha * accum[r][0];
77:         C[index] = (beta == 0.0f) ? product : product + beta * C[index];
78:       }
79:       if (col1 < N) {
80:         const std::size_t index = static_cast<std::size_t>(row) * N + col1;
81:         const float product = alpha * accum[r][1];
82:         C[index] = (beta == 0.0f) ? product : product + beta * C[index];
83:       }
84:     }
85:   }
86: }
87: 
88: extern "C" void run(const float *A, const float *B, float *C, float *scratch,
89:                     int n, int m, int k, float alpha, float beta) {
90:   (void)scratch;
91:   if (n <= 0 || m <= 0) {
92:     return;
93:   }
94:   const int blocksM = n / 64 + (n % 64 != 0);
95:   const int blocksN = m / 64 + (m % 64 != 0);
96:   sgemm_tiled<<<dim3(blocksN, blocksM), dim3(256, 1, 1)>>>(
97:       n, m, k, alpha, A, B, beta, C);
98: }

