3: namespace {
4: constexpr int BM = 64;
5: constexpr int BN = 64;
6: constexpr int BK = 32;
7: constexpr int THREAD_COLS = 32;
8: constexpr int THREAD_ROWS = 8;
9: constexpr int THREADS = THREAD_COLS * THREAD_ROWS;
10: }
11: 
12: __global__ void sgemm_tiled(int M, int N, int K, float alpha, const float *A,
13:                             const float *B, float beta, float *C) {
14:   __shared__ float tileA[BM * BK];
15:   __shared__ float tileB[BK * BN];
16: 
17:   const int tx = static_cast<int>(threadIdx.x);
18:   const int ty = static_cast<int>(threadIdx.y);
19:   const int tid = ty * THREAD_COLS + tx;
20:   const int blockRow = static_cast<int>(blockIdx.y) * BM;
21:   const int blockCol = static_cast<int>(blockIdx.x) * BN;
22: 
23:   float accum[8][2] = {};
24: 
25:   for (int k0 = 0; k0 < K; k0 += BK) {
26:     for (int index = tid; index < BM * BK; index += THREADS) {
27:       const int row = index / BK;
28:       const int k = index % BK;
29:       const int globalRow = blockRow + row;
30:       const int globalK = k0 + k;
31:       tileA[index] = (globalRow < M && globalK < K)
32:                          ? A[static_cast<size_t>(globalRow) * K + globalK]
33:                          : 0.0f;
34:     }
35: 
36:     for (int index = tid; index < BK * BN; index += THREADS) {
37:       const int k = index / BN;
38:       const int col = index % BN;
39:       const int globalK = k0 + k;
40:       const int globalCol = blockCol + col;
41:       tileB[index] = (globalK < K && globalCol < N)
42:                          ? B[static_cast<size_t>(globalK) * N + globalCol]
43:                          : 0.0f;
44:     }
45: 
46:     __syncthreads();
47: 
48:     for (int kk = 0; kk < BK; ++kk) {
49:       const int bIndex = kk * BN + tx;
50:       const float b0 = tileB[bIndex];
51:       const float b1 = tileB[bIndex + THREAD_COLS];
52: #pragma unroll
53:       for (int r = 0; r < 8; ++r) {
54:         const int aIndex = (ty + r * THREAD_ROWS) * BK + kk;
55:         const float a = tileA[aIndex];
56:         accum[r][0] += a * b0;
57:         accum[r][1] += a * b1;
58:       }
59:     }
60: 
61:     __syncthreads();
62:   }
63: 
64: #pragma unroll
65:   for (int r = 0; r < 8; ++r) {
66:     const int row = blockRow + ty + r * THREAD_ROWS;
67:     const int col0 = blockCol + tx;
68:     const int col1 = col0 + THREAD_COLS;
69:     if (row < M) {
70:       if (col0 < N) {
71:         const size_t index = static_cast<size_t>(row) * N + col0;
72:         if (beta == 0.0f) {
73:           C[index] = alpha * accum[r][0];
74:         } else {
75:           C[index] = alpha * accum[r][0] + beta * C[index];
76:         }
77:       }
78:       if (col1 < N) {
79:         const size_t index = static_cast<size_t>(row) * N + col1;
80:         if (beta == 0.0f) {
81:           C[index] = alpha * accum[r][1];
82:         } else {
83:           C[index] = alpha * accum[r][1] + beta * C[index];
84:         }
85:       }
86:     }
87:   }
88: }
89: 
90: extern "C" void run(const float *A, const float *B, float *C, float *scratch,
91:                     int n, int m, int k, float alpha, float beta) {
92:   (void)scratch;
93:   if (n == 0 || m == 0) {
94:     return;
95:   }
96: 
97:   const dim3 grid(static_cast<unsigned int>((m - 1) / BN + 1),
98:                   static_cast<unsigned int>((n - 1) / BM + 1));
99:   const dim3 block(THREAD_COLS, THREAD_ROWS);
100:   sgemm_tiled<<<grid, block>>>(n, m, k, alpha, A, B, beta, C);
101: }

