4: namespace {
5: constexpr int TILE_M = 64;
6: constexpr int TILE_N = 32;
7: constexpr int TILE_K = 32;
8: constexpr int THREADS_X = 32;
9: constexpr int THREADS_Y = 8;
10: constexpr int ROWS_PER_THREAD = 8;
11: 
12: __global__ void sgemm_tiled(int M, int N, int K, float alpha, const float *A,
13:                             const float *B, float beta, float *C) {
14:   __shared__ float shared_a[TILE_M * TILE_K];
15:   __shared__ float shared_b[TILE_K * TILE_N];
16: 
17:   const int lane_col = threadIdx.x;
18:   const int row_group = threadIdx.y;
19:   const int linear_thread = row_group * blockDim.x + lane_col;
20:   float accum[ROWS_PER_THREAD] = {};
21: 
22:   for (int k_base = 0; k_base < K; k_base += TILE_K) {
23:     for (int idx = linear_thread; idx < TILE_M * TILE_K;
24:          idx += THREADS_X * THREADS_Y) {
25:       const int local_row = idx / TILE_K;
26:       const int local_k = idx % TILE_K;
27:       const int global_row = blockIdx.y * TILE_M + local_row;
28:       const int global_k = k_base + local_k;
29:       shared_a[idx] = (global_row < M && global_k < K)
30:                           ? A[static_cast<size_t>(global_row) * K + global_k]
31:                           : 0.0f;
32:     }
33: 
34:     for (int idx = linear_thread; idx < TILE_K * TILE_N;
35:          idx += THREADS_X * THREADS_Y) {
36:       const int local_k = idx / TILE_N;
37:       const int local_col = idx % TILE_N;
38:       const int global_k = k_base + local_k;
39:       const int global_col = blockIdx.x * TILE_N + local_col;
40:       shared_b[idx] = (global_k < K && global_col < N)
41:                           ? B[static_cast<size_t>(global_k) * N + global_col]
42:                           : 0.0f;
43:     }
44: 
45:     __syncthreads();
46: 
47:     #pragma unroll
48:     for (int kk = 0; kk < TILE_K; ++kk) {
49:       const float b_value = shared_b[kk * TILE_N + lane_col];
50:       #pragma unroll
51:       for (int r = 0; r < ROWS_PER_THREAD; ++r) {
52:         const int local_row = row_group + r * THREADS_Y;
53:         const float a_value = shared_a[local_row * TILE_K + kk];
54:         accum[r] += a_value * b_value;
55:       }
56:     }
57: 
58:     __syncthreads();
59:   }
60: 
61:   const int global_col = blockIdx.x * TILE_N + lane_col;
62:   #pragma unroll
63:   for (int r = 0; r < ROWS_PER_THREAD; ++r) {
64:     const int global_row = blockIdx.y * TILE_M + row_group + r * THREADS_Y;
65:     if (global_row < M && global_col < N) {
66:       const size_t index = static_cast<size_t>(global_row) * N + global_col;
67:       float result = alpha * accum[r];
68:       if (beta != 0.0f) {
69:         result += beta * C[index];
70:       }
71:       C[index] = result;
72:     }
73:   }
74: }
75: }  // namespace
76: 
77: extern "C" void run(const float *A, const float *B, float *C, float *scratch,
78:                     int n, int m, int k, float alpha, float beta) {
79:   (void)scratch;
80:   if (n <= 0 || m <= 0) {
81:     return;
82:   }
83: 
84:   const int grid_x = m / TILE_N + (m % TILE_N != 0);
85:   const int grid_y = n / TILE_M + (n % TILE_M != 0);
86:   sgemm_tiled<<<dim3(grid_x, grid_y), dim3(THREADS_X, THREADS_Y)>>>(
87:       n, m, k, alpha, A, B, beta, C);
88: }

