5: __global__ void sgemm_warp_register_2x3(int M, int N, int K, float alpha,
6:                                        const float *A, const float *B,
7:                                        float beta, float *C) {
8:   const int lane = threadIdx.x;
9:   const size_t row_base = static_cast<size_t>(blockIdx.y) * 8u +
10:                           static_cast<size_t>(threadIdx.y) * 2u;
11:   const size_t col0 = static_cast<size_t>(blockIdx.x) * 96u +
12:                       static_cast<size_t>(lane);
13:   const size_t col1 = col0 + 32u;
14:   const size_t col2 = col0 + 64u;
15:   const size_t m_size = static_cast<size_t>(M);
16:   const size_t n_size = static_cast<size_t>(N);
17:   const size_t k_size = static_cast<size_t>(K);
18:   constexpr unsigned int full_warp_mask = 0xffffffffu;
19: 
20:   float acc00 = 0.0f;
21:   float acc01 = 0.0f;
22:   float acc02 = 0.0f;
23:   float acc10 = 0.0f;
24:   float acc11 = 0.0f;
25:   float acc12 = 0.0f;
26: 
27:   for (int kk = 0; kk < K; ++kk) {
28:     const size_t b_row = static_cast<size_t>(kk) * n_size;
29:     const float b0 = col0 < n_size ? B[b_row + col0] : 0.0f;
30:     const float b1 = col1 < n_size ? B[b_row + col1] : 0.0f;
31:     const float b2 = col2 < n_size ? B[b_row + col2] : 0.0f;
32: 
33:     float a0 = lane == 0 && row_base < m_size
34:                    ? A[row_base * k_size + static_cast<size_t>(kk)]
35:                    : 0.0f;
36:     float a1 = lane == 0 && row_base + 1u < m_size
37:                    ? A[(row_base + 1u) * k_size + static_cast<size_t>(kk)]
38:                    : 0.0f;
39: 
40:     a0 = __shfl_sync(full_warp_mask, a0, 0);
41:     a1 = __shfl_sync(full_warp_mask, a1, 0);
42: 
43:     acc00 = __fmaf_rn(a0, b0, acc00);
44:     acc01 = __fmaf_rn(a0, b1, acc01);
45:     acc02 = __fmaf_rn(a0, b2, acc02);
46:     acc10 = __fmaf_rn(a1, b0, acc10);
47:     acc11 = __fmaf_rn(a1, b1, acc11);
48:     acc12 = __fmaf_rn(a1, b2, acc12);
49:   }
50: 
51:   if (row_base < m_size) {
52:     if (col0 < n_size) {
53:       const size_t index = row_base * n_size + col0;
54:       C[index] = alpha * acc00 + beta * C[index];
55:     }
56:     if (col1 < n_size) {
57:       const size_t index = row_base * n_size + col1;
58:       C[index] = alpha * acc01 + beta * C[index];
59:     }
60:     if (col2 < n_size) {
61:       const size_t index = row_base * n_size + col2;
62:       C[index] = alpha * acc02 + beta * C[index];
63:     }
64:   }
65:   if (row_base + 1u < m_size) {
66:     if (col0 < n_size) {
67:       const size_t index = (row_base + 1u) * n_size + col0;
68:       C[index] = alpha * acc10 + beta * C[index];
69:     }
70:     if (col1 < n_size) {
71:       const size_t index = (row_base + 1u) * n_size + col1;
72:       C[index] = alpha * acc11 + beta * C[index];
73:     }
74:     if (col2 < n_size) {
75:       const size_t index = (row_base + 1u) * n_size + col2;
76:       C[index] = alpha * acc12 + beta * C[index];
77:     }
78:   }
79: }
