sources.text:
1: #include <cuda_runtime.h>
2: #include <stdint.h>
3: 
4: namespace {
5: 
6: constexpr int kBlockX = 32;
7: constexpr int kBlockY = 8;
8: constexpr int kTileM = 16;
9: constexpr int kTileN = 64;
10: constexpr int kTileK = 32;
11: constexpr int kThreads = kBlockX * kBlockY;
12: 
13: template <bool Async>
14: __device__ __forceinline__ void copy_scalar(float *dst, const float *src) {
15:   if (Async) {
16:     const unsigned int shared_address =
17:         static_cast<unsigned int>(__cvta_generic_to_shared(dst));
18:     asm volatile("cp.async.ca.shared.global [%0], [%1], 4;"
19:                  :
20:                  : "r"(shared_address), "l"(src)
21:                  : "memory");
22:   } else {
23:     *dst = *src;
24:   }
25: }
26: 
27: template <bool Async>
28: __device__ __forceinline__ void copy_vector(float *dst, const float *src) {
29:   if (Async) {
30:     const unsigned int shared_address =
31:         static_cast<unsigned int>(__cvta_generic_to_shared(dst));
32:     asm volatile("cp.async.ca.shared.global [%0], [%1], 16;"
33:                  :
34:                  : "r"(shared_address), "l"(src)
35:                  : "memory");
36:   } else {
37:     const float4 values = *reinterpret_cast<const float4 *>(src);
38:     *reinterpret_cast<float4 *>(dst) = values;
39:   }
40: }
41: 
42: template <bool Async>
43: __device__ __forceinline__ void commit_copies() {
44:   if (Async) {
45:     asm volatile("cp.async.commit_group;" ::: "memory");
46:   }
47: }
48: 
49: template <bool Async>
50: __device__ __forceinline__ void wait_for_copies() {
51:   if (Async) {
52:     asm volatile("cp.async.wait_group 0;" ::: "memory");
53:   }
54: }
55: 
56: __device__ __forceinline__ bool aligned_16(const void *ptr) {
57:   return (reinterpret_cast<uintptr_t>(ptr) & static_cast<uintptr_t>(15)) == 0;
58: }
59: 
60: template <bool Async, bool Vectorized>
61: __device__ __forceinline__ void stage_tile(
62:     const float *A, const float *B, int M, int N, int K, int row_origin,
63:     int col_origin, int k_origin, float *shared_a, float *shared_b) {
64:   const int tid = static_cast<int>(threadIdx.y) * kBlockX +
65:                   static_cast<int>(threadIdx.x);
66: 
67:   // Each group covers four adjacent K values for one A row.
68:   constexpr int kAGroups = kTileM * (kTileK / 4);
69:   for (int group = tid; group < kAGroups; group += kThreads) {
70:     const int tile_row = group / (kTileK / 4);
71:     const int group_k = group % (kTileK / 4);
72:     const int row = row_origin + tile_row;
73:     const int tile_k = group_k * 4;
74:     const int k = k_origin + tile_k;
75:     float *dst = &shared_a[tile_row * kTileK + tile_k];
76:     const bool base_valid = row < M && k < K;
77:     const float *src = base_valid
78:                            ? A + static_cast<unsigned long long>(row) * K + k
79:                            : A;
80:     const bool full_valid = row < M && K >= 4 && k <= K - 4;
81: 
82:     if (Vectorized && full_valid && aligned_16(src) && aligned_16(dst)) {
83:       copy_vector<Async>(dst, src);
84:     } else {
85:       for (int j = 0; j < 4; ++j) {
86:         if (row < M && k + j < K) {
87:           copy_scalar<Async>(dst + j, src + j);
88:         } else {
89:           dst[j] = 0.0f;
90:         }
91:       }
92:     }
93:   }
94: 
95:   // Each group covers four adjacent columns for one B row.
96:   constexpr int kBGroups = kTileK * (kTileN / 4);
97:   for (int group = tid; group < kBGroups; group += kThreads) {
98:     const int tile_k = group / (kTileN / 4);
99:     const int group_col = group % (kTileN / 4);
100:     const int k = k_origin + tile_k;
101:     const int tile_col = group_col * 4;
102:     const int col = col_origin + tile_col;
103:     float *dst = &shared_b[tile_k * kTileN + tile_col];
104:     const bool base_valid = k < K && col < N;
105:     const float *src = base_valid
106:                            ? B + static_cast<unsigned long long>(k) * N + col
107:                            : B;
108:     const bool full_valid = k < K && N >= 4 && col <= N - 4;
109: 
110:     if (Vectorized && full_valid && aligned_16(src) && aligned_16(dst)) {
111:       copy_vector<Async>(dst, src);
112:     } else {
113:       for (int j = 0; j < 4; ++j) {
114:         if (k < K && col + j < N) {
115:           copy_scalar<Async>(dst + j, src + j);
116:         } else {
117:           dst[j] = 0.0f;
118:         }
119:       }
120:     }
121:   }
122: }
123: 
124: template <bool Async, bool Vectorized>
125: __global__ void sgemm_tiled(int M, int N, int K, float alpha, const float *A,
126:                             const float *B, float beta, float *C) {
127:   __shared__ __align__(16) float shared_a[2][kTileM * kTileK];
128:   __shared__ __align__(16) float shared_b[2][kTileK * kTileN];
129: 
130:   const int row_origin = static_cast<int>(blockIdx.y) * kTileM;
131:   const int col_origin = static_cast<int>(blockIdx.x) * kTileN;
132:   const int row0 = row_origin + static_cast<int>(threadIdx.y);
133:   const int row1 = row0 + kBlockY;
134:   const int col0 = col_origin + static_cast<int>(threadIdx.x);
135:   const int col1 = col0 + kBlockX;
136:   const int k_tiles = K > 0 ? K / kTileK + ((K % kTileK) != 0) : 0;
137: 
138:   float acc00 = 0.0f;
139:   float acc01 = 0.0f;
140:   float acc10 = 0.0f;
141:   float acc11 = 0.0f;
142: 
143:   if (k_tiles > 0) {
144:     stage_tile<Async, Vectorized>(A, B, M, N, K, row_origin, col_origin, 0,
145:                                   shared_a[0], shared_b[0]);
146:     commit_copies<Async>();
147:     wait_for_copies<Async>();
148:     __syncthreads();
149: 
150:     int current_buffer = 0;
